import './styles.css'
import { autoSnapshot, backupSummary, createSnapshot, deleteClass, deleteStudent, exportData, getSnapshot, importData, listSnapshots, loadAttendance, loadBilling, loadClasses, loadStudents, saveAttendanceMark, saveBilling, saveClasses, saveStudents, storageMode } from './storage.js'

const now = new Date()
const paymentTemplateKey = 'hebrew-with-smadar-payment-template-v1'
const defaultPaymentTemplate = 'הי {parent},\nתזכורת לתשלום עבור שיעורי העברית לחודש {month}:\n{details}\nסה"כ לתשלום: {total}\nתודה, סמדר'
function readPaymentTemplate() { try { return localStorage.getItem(paymentTemplateKey) || defaultPaymentTemplate } catch { return defaultPaymentTemplate } }
const validViews = ['students', 'classes', 'attendance', 'billing', 'reports', 'communication', 'backup']
const initialView = validViews.includes(window.location.hash.slice(1)) ? window.location.hash.slice(1) : 'students'
const state = { view: initialView, students: [], classes: [], attendance: {}, billing: {}, attendanceMonth: now.getMonth(), attendanceYear: now.getFullYear(), attendanceClassId: '', billingMonth: now.getMonth(), billingYear: now.getFullYear(), reportsYear: now.getFullYear(), commClassId: '', commType: 'cancel', commDate: '', commNewDate: '', commTime: '', classMessage: undefined, paymentTemplate: readPaymentTemplate() }
const app = document.querySelector('#app')
const accents = ['teal', 'coral', 'gold', 'blue', 'lavender', 'mint']
let statusMessage = storageMode === 'cloud' ? 'Cloud sync ready' : 'Saved in this browser'

const initials = (name) => name.trim().split(/\s+/).map((part) => part[0]).join('').slice(0, 2).toUpperCase()
const saveStudentsData = () => saveStudents(state.students).catch(() => setStatus('Saved on this device. Cloud sync needs the Supabase setup.'))
const saveClassesData = () => saveClasses(state.classes).catch(() => setStatus('Classes saved on this device. Cloud sync needs the Supabase setup.'))
const saveAttendanceData = (key) => saveAttendanceMark(state.attendance, key).catch(() => setStatus('Attendance saved on this device. Cloud sync needs the Supabase setup.'))
const saveBillingData = () => { billingFamilies().forEach((family) => { const key = billingKey(family.parent); state.billing[key] = { ...(state.billing[key] || {}), balanceForward: family.balance - family.credit } }); return saveBilling(state.billing).catch(() => setStatus('Billing saved on this device. Cloud sync needs the Supabase setup.')) }
function setStatus(message) { statusMessage = message; document.querySelector('#storage-status')?.replaceChildren(document.createTextNode(message)) }

function render() {
  const isClasses = state.view === 'classes'
  const isAttendance = state.view === 'attendance'
  const isBilling = state.view === 'billing'
  const isReports = state.view === 'reports'
  const isBackup = state.view === 'backup'
  const isCommunication = state.view === 'communication'
  app.innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand"><img src="/Logo.jpeg" alt="Hebrew with Smadar logo" /><div><strong>Hebrew with Smadar</strong><span>Private lesson studio</span></div></div><div class="sidebar-label">Workspace</div><nav><button class="nav-item ${!isClasses && !isAttendance && !isBilling && !isReports && !isBackup && !isCommunication ? 'active' : ''}" data-view="students"><span class="nav-icon">◉</span>Students & families</button><button class="nav-item ${isClasses ? 'active' : ''}" data-view="classes"><span class="nav-icon">▦</span>Class structure</button><button class="nav-item ${isAttendance ? 'active' : ''}" data-view="attendance"><span class="nav-icon">✓</span>Attendance</button><button class="nav-item ${isBilling ? 'active' : ''}" data-view="billing"><span class="nav-icon">$</span>Billing & payments</button><button class="nav-item ${isReports ? 'active' : ''}" data-view="reports"><span class="nav-icon">◒</span>Reports</button><button class="nav-item ${isCommunication ? 'active' : ''}" data-view="communication"><span class="nav-icon">✉</span>Communication</button><button class="nav-item ${isBackup ? 'active' : ''}" data-view="backup"><span class="nav-icon">⟲</span>Backup & restore</button></nav><div class="sidebar-bottom"><div class="mini-profile"><span>SS</span><div><strong>Smadar</strong><small>Teacher & owner</small></div></div></div></aside><main class="main-content"><header class="topbar"><div class="mobile-brand"><img src="/Logo.jpeg" alt="" /><strong>Hebrew with Smadar</strong></div><div class="breadcrumb"><span>Workspace</span><b>/</b><strong>${isClasses ? 'Class structure' : isAttendance ? 'Attendance' : isBilling ? 'Billing & payments' : isReports ? 'Reports' : isCommunication ? 'Communication' : isBackup ? 'Backup & restore' : 'Students & families'}</strong></div><div class="mobile-nav"><button class="mobile-nav-button ${!isClasses && !isAttendance && !isBilling && !isReports && !isBackup && !isCommunication ? 'active' : ''}" data-view="students">Students</button><button class="mobile-nav-button ${isClasses ? 'active' : ''}" data-view="classes">Classes</button><button class="mobile-nav-button ${isAttendance ? 'active' : ''}" data-view="attendance">Attendance</button><button class="mobile-nav-button ${isBilling ? 'active' : ''}" data-view="billing">Billing</button><button class="mobile-nav-button ${isReports ? 'active' : ''}" data-view="reports">Reports</button><button class="mobile-nav-button ${isCommunication ? 'active' : ''}" data-view="communication">Messages</button><button class="mobile-nav-button ${isBackup ? 'active' : ''}" data-view="backup">Backup</button></div><div class="teacher-avatar">SS</div></header>${isClasses ? classesPage() : isAttendance ? attendancePage() : isBilling ? billingPage() : isReports ? reportsPage() : isCommunication ? communicationPage() : isBackup ? backupPage() : studentsPage()}</main></div><div id="modal-root"></div>`
  app.querySelector('.brand span').textContent = 'לומדים עברית עם סמדר'
  attachEvents()
  applyFrozenColumns()
}

function studentsPage() { return `<div class="page-wrap"><div class="page-header"><div><div class="eyebrow">STEP 1 · YOUR ROSTER</div><h1>Students & families</h1><p>Add each student and their parent or guardian contact.</p></div><button class="primary-button" data-action="add-student"><span>+</span> Add student</button></div><div class="intro-banner"><div class="intro-mark">01</div><div><strong>Start with your student list</strong><p>One parent can be connected to more than one student. You can edit every detail at any time.</p></div><span class="intro-line"></span></div><div class="toolbar"><div class="search-box"><span>⌕</span><input id="student-search" placeholder="Search students or parents..." /></div><span class="toolbar-count" id="student-count">${state.students.length} ${state.students.length === 1 ? 'student' : 'students'}</span><span class="storage-status" id="storage-status">${statusMessage}</span></div><div class="panel table-panel"><div class="table-heading"><div><h2>Student roster</h2><p class="heading-note">Your families and their contact details</p></div></div>${state.students.length ? `<div class="table-wrap"><table class="roster-table" data-freeze="2"><thead><tr><th>Student</th><th>Parent / guardian</th><th>Phone</th><th></th></tr></thead><tbody id="student-rows">${studentRows(state.students)}</tbody></table></div>` : emptyStudentState()}</div></div>` }
function classesPage() { return `<div class="page-wrap"><div class="page-header"><div><div class="eyebrow">STEP 2 · ORGANIZE YOUR WEEK</div><h1>Class structure</h1><p>Create groups, set their weekly day, and define the cost per student.</p></div><button class="primary-button" data-action="add-class"><span>+</span> Add class</button></div><div class="intro-banner class-intro"><div class="intro-mark">02</div><div><strong>Build your teaching groups</strong><p>Each class can have its own schedule, price, and student list. You can update these details any time.</p></div><span class="intro-line"></span></div><div class="toolbar"><span class="toolbar-count class-count">${state.classes.length} ${state.classes.length === 1 ? 'class' : 'classes'}</span><span class="storage-status" id="storage-status">${statusMessage}</span></div>${state.classes.length ? `<div class="class-grid">${state.classes.map(classCard).join('')}</div>` : emptyClassState()}</div>` }
function attendancePage() { const monthName = new Intl.DateTimeFormat('en-US', { month: 'long' }).format(new Date(state.attendanceYear, state.attendanceMonth, 1)); const daysInMonth = new Date(state.attendanceYear, state.attendanceMonth + 1, 0).getDate(); const selectedClass = state.classes.find((group) => String(group.id) === String(state.attendanceClassId)); const students = selectedClass ? state.students.filter((student) => (selectedClass.studentIds || []).includes(student.id)) : []; return `<div class="page-wrap"><div class="page-header"><div><div class="eyebrow">STEP 3 · TRACK LESSONS</div><h1>Attendance</h1><p>Mark which students attended each lesson in the selected month.</p></div></div><div class="attendance-toolbar"><div class="attendance-controls"><label>Class<select id="attendance-class">${state.classes.length ? state.classes.map((group) => `<option value="${group.id}" ${String(group.id) === String(state.attendanceClassId) ? 'selected' : ''}>Class ${group.number} · ${classSchedule(group)}</option>`).join('') : '<option>No classes yet</option>'}</select></label><label>Month<select id="attendance-month">${Array.from({ length: 12 }, (_, month) => `<option value="${month}" ${month === state.attendanceMonth ? 'selected' : ''}>${new Intl.DateTimeFormat('en-US', { month: 'long' }).format(new Date(2000, month, 1))}</option>`).join('')}</select></label><label>Year<input id="attendance-year" type="number" min="2020" max="2100" value="${state.attendanceYear}" /></label></div><div class="attendance-summary"><div class="summary-ring">${attendanceTotal(students, daysInMonth)}</div><div><strong>${monthName} ${state.attendanceYear}</strong><small>attendance marks</small></div></div></div>${state.classes.length ? `<div class="panel attendance-sheet"><div class="sheet-heading"><div><h2>${selectedClass ? `Class ${selectedClass.number} · ${classSchedule(selectedClass)}` : 'Attendance sheet'}</h2><p class="heading-note">Click a day for each student to mark attendance.</p></div><span class="attendance-legend"><i></i> Present</span></div>${students.length ? attendanceTable(students, daysInMonth) : '<div class="empty-state compact-empty"><div class="empty-icon">○</div><h2>No students assigned</h2><p>Assign students to this class from Class structure.</p></div>'}</div>` : '<div class="panel empty-state"><div class="empty-icon">✓</div><h2>Create a class first</h2><p>Attendance sheets are generated from the students assigned to each class.</p><button class="primary-button" data-view="classes">Open class structure</button></div>'}</div>` }
function billingPage() { const monthName = new Intl.DateTimeFormat('en-US', { month: 'long' }).format(new Date(state.billingYear, state.billingMonth, 1)); const families = billingFamilies(); const totals = families.reduce((summary, family) => ({ due: summary.due + family.total, paid: summary.paid + family.paid, balance: summary.balance + family.balance }), { due: 0, paid: 0, balance: 0 }); return `<div class="page-wrap"><div class="page-header"><div><div class="eyebrow">STEP 4 · COLLECT PAYMENTS</div><h1>Billing & payments</h1><p>Review each family’s monthly total, record how it was paid, and track the remaining balance.</p></div></div><div class="billing-toolbar"><label>Month<select id="billing-month">${Array.from({ length: 12 }, (_, month) => `<option value="${month}" ${month === state.billingMonth ? 'selected' : ''}>${new Intl.DateTimeFormat('en-US', { month: 'long' }).format(new Date(2000, month, 1))}</option>`).join('')}</select></label><label>Year<input id="billing-year" type="number" min="2020" max="2100" value="${state.billingYear}" /></label><div class="billing-period">${monthName} ${state.billingYear}</div></div><div class="billing-stats"><div><span>Total due</span><strong>$${totals.due.toFixed(2)}</strong></div><div><span>Paid</span><strong class="green-text">$${totals.paid.toFixed(2)}</strong></div><div><span>Outstanding</span><strong class="coral-text">$${totals.balance.toFixed(2)}</strong></div><div><span>Families</span><strong>${families.length}</strong></div></div>${families.length ? `<div class="panel billing-panel"><div class="table-heading"><div><h2>Monthly family accounts</h2><p class="heading-note">Charges are the class price × lessons attended this month.</p></div></div><div class="table-wrap"><table class="billing-table" data-freeze="2"><thead><tr><th>Parent / guardian</th><th>Students & classes</th><th>Total due</th><th>Paid</th><th>Balance</th><th>Payment method</th><th></th></tr></thead><tbody>${families.map(billingRow).join('')}</tbody></table></div></div>` : '<div class="panel empty-state"><div class="empty-icon">$</div><h2>No billable families yet</h2><p>Assign students to classes and add a monthly cost to generate billing.</p><button class="primary-button" data-view="classes">Open class structure</button></div>'}</div>` }
function reportsPage() { const report = buildReport(); const maxRevenue = Math.max(...report.months.flatMap((month) => [month.paid, month.due]), 1); const maxActivity = Math.max(...report.months.map((month) => Math.max(month.studentLessons, month.classLessons)), 1); return `<div class="page-wrap"><div class="page-header"><div><div class="eyebrow">STEP 5 · UNDERSTAND YOUR BUSINESS</div><h1>Reports</h1><p>Track annual income and compare lesson activity across students and classes.</p></div><label class="report-year">Year<input id="reports-year" type="number" min="2020" max="2100" value="${state.reportsYear}" /></label></div><div class="report-stats"><div><span>Annual income</span><strong>$${report.totalPaid.toFixed(2)}</strong><small>Payments recorded</small></div><div><span>Annual charges</span><strong>$${report.totalDue.toFixed(2)}</strong><small>Before payments</small></div><div><span>Lessons by students</span><strong>${report.totalStudentLessons}</strong><small>Attendance marks</small></div><div><span>Class lessons</span><strong>${report.totalClassLessons}</strong><small>Unique class dates</small></div></div><div class="report-grid"><section class="panel chart-panel"><div class="chart-heading"><div><h2>Monthly income</h2><p class="heading-note">Paid amount compared with monthly charges</p></div><div class="chart-legend"><span class="legend-paid"></span>Paid <span class="legend-due"></span>Due</div></div><div class="bar-chart revenue-chart">${report.months.map((month) => `<div class="bar-group"><div class="bar-pair"><span class="bar paid-bar" style="height:${Math.max((month.paid / maxRevenue) * 100, month.paid ? 4 : 0)}%" title="Paid $${month.paid.toFixed(2)}"></span><span class="bar due-bar" style="height:${Math.max((month.due / maxRevenue) * 100, month.due ? 4 : 0)}%" title="Due $${month.due.toFixed(2)}"></span></div><small>${month.label}</small></div>`).join('')}</div></section><section class="panel chart-panel"><div class="chart-heading"><div><h2>Lesson activity</h2><p class="heading-note">Monthly comparison of student marks and class sessions</p></div><div class="chart-legend"><span class="legend-students"></span>Students <span class="legend-classes"></span>Classes</div></div><div class="bar-chart activity-chart">${report.months.map((month) => `<div class="bar-group"><div class="bar-pair"><span class="bar students-bar" style="height:${Math.max((month.studentLessons / maxActivity) * 100, month.studentLessons ? 4 : 0)}%" title="${month.studentLessons} student marks"></span><span class="bar classes-bar" style="height:${Math.max((month.classLessons / maxActivity) * 100, month.classLessons ? 4 : 0)}%" title="${month.classLessons} class lessons"></span></div><small>${month.label}</small></div>`).join('')}</div></section></div><div class="panel report-table"><div class="table-heading"><div><h2>Monthly breakdown</h2><p class="heading-note">Detailed figures for ${state.reportsYear}</p></div></div><div class="table-wrap"><table><thead><tr><th>Month</th><th>Paid</th><th>Due</th><th>Student lessons</th><th>Class lessons</th></tr></thead><tbody>${report.months.map((month) => `<tr><td><strong>${month.fullLabel}</strong></td><td class="green-text">$${month.paid.toFixed(2)}</td><td>$${month.due.toFixed(2)}</td><td>${month.studentLessons}</td><td>${month.classLessons}</td></tr>`).join('')}</tbody></table></div></div>${attendanceTrendsSection()}</div>` }
function attendanceTrendsSection() { const months = Array.from({ length: 12 }, (_, month) => ({ month, label: new Intl.DateTimeFormat('en-US', { month: 'short' }).format(new Date(state.reportsYear, month, 1)) })); const classRows = state.classes.map((group) => { const counts = months.map(({ month }) => attendanceClassDates(group.id, state.reportsYear, month)); return { label: `Class ${group.number}`, counts } }); const studentRows = state.students.map((student) => { const counts = months.map(({ month }) => attendanceStudentTotal(student.id, state.reportsYear, month)); return { label: student.name, counts } }); return `<section class="attendance-trends"><div class="trend-heading"><div><div class="eyebrow">ATTENDANCE TRENDS</div><h2>Class and student attendance</h2><p class="heading-note">Zero marks highlight students missing a month; low class counts highlight classes meeting less often.</p></div></div><div class="trend-grid"><div class="panel trend-panel"><h3>Lessons by class</h3><div class="trend-table-wrap"><table class="trend-table"><thead><tr><th>Class</th>${months.map((item) => `<th>${item.label}</th>`).join('')}</tr></thead><tbody>${classRows.length ? classRows.map((row) => `<tr><td><strong>${row.label}</strong></td>${row.counts.map((count) => `<td class="${count <= 1 ? 'trend-low' : ''}">${count}</td>`).join('')}</tr>`).join('') : '<tr><td colspan="13" class="muted">No classes configured.</td></tr>'}</tbody></table></div></div><div class="panel trend-panel"><h3>Attendance by student</h3><div class="trend-table-wrap"><table class="trend-table"><thead><tr><th>Student</th>${months.map((item) => `<th>${item.label}</th>`).join('')}</tr></thead><tbody>${studentRows.length ? studentRows.map((row) => `<tr><td><strong>${row.label}</strong></td>${row.counts.map((count) => `<td class="${count === 0 ? 'trend-empty' : ''}">${count}</td>`).join('')}</tr>`).join('') : '<tr><td colspan="13" class="muted">No students configured.</td></tr>'}</tbody></table></div></div></div></section>` }
function buildReport() { const months = Array.from({ length: 12 }, (_, monthIndex) => { const reportMonth = { index: monthIndex, label: new Intl.DateTimeFormat('en-US', { month: 'short' }).format(new Date(state.reportsYear, monthIndex, 1)), fullLabel: new Intl.DateTimeFormat('en-US', { month: 'long' }).format(new Date(state.reportsYear, monthIndex, 1)), paid: 0, due: reportTotalDue(state.reportsYear, monthIndex), studentLessons: 0, classLessons: 0 }; Object.entries(state.billing).forEach(([key, value]) => { const separator = key.lastIndexOf(':'); const period = key.slice(separator + 1); if (period === `${state.reportsYear}-${String(monthIndex + 1).padStart(2, '0')}`) reportMonth.paid += Number(value.amountPaid || 0) }); const dates = new Set(); Object.entries(state.attendance).forEach(([key, present]) => { if (!present) return; const [classId, date] = key.split(':'); const [year, attendanceMonth] = date.split('-').map(Number); if (year === state.reportsYear && attendanceMonth === monthIndex + 1) { reportMonth.studentLessons += 1; dates.add(`${classId}:${date}`) } }); reportMonth.classLessons = [...dates].length; return reportMonth }); return { months, totalPaid: months.reduce((sum, month) => sum + month.paid, 0), totalDue: months.reduce((sum, month) => sum + month.due, 0), totalStudentLessons: months.reduce((sum, month) => sum + month.studentLessons, 0), totalClassLessons: months.reduce((sum, month) => sum + month.classLessons, 0) } }
function reportTotalDue(year, monthIndex) { const parents = new Set(state.students.map((student) => student.parent || 'No parent listed')); return [...parents].reduce((total, parent) => total + Math.max(reportParentBaseDue(parent, year, monthIndex) + reportPreviousBalance(parent, year, monthIndex), 0), 0) }
function reportParentBaseDue(parent, year, monthIndex) { return state.classes.reduce((total, group) => total + state.students.filter((student) => (student.parent || 'No parent listed') === parent && (group.studentIds || []).includes(student.id)).reduce((lessons, student) => lessons + studentLessonCount(student.id, group.id, year, monthIndex), 0) * Number(group.cost || 0), 0) }
function reportPreviousBalance(parent, year, monthIndex) { const previousMonth = monthIndex === 0 ? 11 : monthIndex - 1; const previousYear = monthIndex === 0 ? year - 1 : year; const payment = state.billing[billingKeyFor(parent, previousYear, previousMonth)]; if (!payment) return 0; if (payment.balanceForward !== undefined) return Number(payment.balanceForward || 0); return reportMonthlyDue(parent, previousYear, previousMonth) - Number(payment.amountPaid || 0) }
function reportMonthlyDue(parent, year, monthIndex) { return Math.max(reportParentBaseDue(parent, year, monthIndex) + reportPreviousBalance(parent, year, monthIndex), 0) }
function studentLessonCount(studentId, classId, year, monthIndex) { const prefix = `${classId}:${year}-${String(monthIndex + 1).padStart(2, '0')}-`; return Object.entries(state.attendance).filter(([key, present]) => present && key.startsWith(prefix) && Number(key.split(':')[2]) === studentId).length }
function billingFamilies() { const families = new Map(); state.classes.forEach((group) => { state.students.filter((student) => (group.studentIds || []).includes(student.id)).forEach((student) => { const lessons = studentLessonCount(student.id, group.id, state.billingYear, state.billingMonth); if (!lessons) return; const parent = student.parent || 'No parent listed'; const family = families.get(parent) || { parent, students: [], total: 0, paid: 0, items: [], charges: [] }; family.students.push(student.name); family.items.push(`Class ${group.number} · ${classSchedule(group)} · ${lessons} ${lessons === 1 ? 'lesson' : 'lessons'} × $${Number(group.cost || 0)}`); family.charges.push({ number: group.number, lessons, cost: Number(group.cost || 0) }); family.total += lessons * Number(group.cost || 0); families.set(parent, family) }) }); return [...families.values()].map((family) => { const payment = state.billing[billingKey(family.parent)] || { amountPaid: 0, paymentMethod: '' }; const previousDate = new Date(state.billingYear, state.billingMonth - 1, 1); const previousPayment = state.billing[billingKeyFor(family.parent, previousDate.getFullYear(), previousDate.getMonth())]; const previousBalance = previousPayment ? Number(previousPayment.balanceForward ?? (family.total - Number(previousPayment.amountPaid || 0))) : 0; const amountBeforePayment = family.total + previousBalance; family.baseTotal = family.total; family.previousBalance = previousBalance; family.total = Math.max(amountBeforePayment, 0); family.paid = Number(payment.amountPaid || 0); family.balance = Math.max(amountBeforePayment - family.paid, 0); family.credit = Math.max(family.paid - amountBeforePayment, 0); family.paymentMethod = payment.paymentMethod || ''; return family }) }
function billingKeyFor(parent, year, month) { return `${parent}:${year}-${String(month + 1).padStart(2, '0')}` }
function billingKey(parent) { return billingKeyFor(parent, state.billingYear, state.billingMonth) }
function billingRow(family) { const previousLabel = family.previousBalance > 0 ? `Previous balance +$${family.previousBalance.toFixed(2)}` : family.previousBalance < 0 ? `Previous credit -$${Math.abs(family.previousBalance).toFixed(2)}` : 'No previous balance'; return `<tr><td><strong class="billing-parent">${family.parent}</strong></td><td><div class="billing-students">${family.students.map((student, index) => `<span>${student} <small>${family.items[index]}</small></span>`).join('')}</div></td><td><strong>$${family.total.toFixed(2)}</strong><small class="billing-carry">${previousLabel}</small></td><td><input class="paid-input" data-parent="${family.parent}" type="number" min="0" step="0.01" value="${family.paid.toFixed(2)}" aria-label="Amount paid for ${family.parent}" /></td><td><strong class="${family.balance ? 'coral-text' : 'green-text'}">$${family.balance.toFixed(2)}</strong>${family.credit ? `<small class="green-text billing-carry">Credit $${family.credit.toFixed(2)} forward</small>` : ''}</td><td><select class="payment-method-select" data-parent="${family.parent}" aria-label="Payment method for ${family.parent}"><option value="">Not paid</option><option value="PayPal" ${family.paymentMethod === 'PayPal' ? 'selected' : ''}>PayPal</option><option value="Zelle" ${family.paymentMethod === 'Zelle' ? 'selected' : ''}>Zelle</option><option value="Venmo" ${family.paymentMethod === 'Venmo' ? 'selected' : ''}>Venmo</option></select></td><td><button class="row-action" data-action="save-payment" data-parent="${family.parent}">Save</button></td></tr>` }
function communicationPage() { const monthName = new Intl.DateTimeFormat('en-US', { month: 'long' }).format(new Date(state.billingYear, state.billingMonth, 1)); const selectedClass = state.classes.find((group) => String(group.id) === String(state.commClassId)); const notices = [['cancel', 'Cancel a lesson'], ['time', 'Change the time'], ['day', 'Move to another day']]; return `<div class="page-wrap"><div class="page-header"><div><div class="eyebrow">STEP 6 · STAY IN TOUCH</div><h1>Communication</h1><p>Send payment requests and class updates to parents on WhatsApp.</p></div></div><div class="panel comm-panel"><div class="table-heading"><div><h2>Monthly payment requests</h2><p class="heading-note">Amounts come from Billing & payments, including any previous balance and payments already recorded.</p></div></div><div class="billing-toolbar comm-toolbar"><label>Month<select id="comm-month">${Array.from({ length: 12 }, (_, month) => `<option value="${month}" ${month === state.billingMonth ? 'selected' : ''}>${new Intl.DateTimeFormat('en-US', { month: 'long' }).format(new Date(2000, month, 1))}</option>`).join('')}</select></label><label>Year<input id="comm-year" type="number" min="2020" max="2100" value="${state.billingYear}" /></label><div class="billing-period">${monthName} ${state.billingYear}</div></div><label class="comm-message">Message template<textarea id="payment-template" rows="7" dir="rtl">${escapeHtml(state.paymentTemplate)}</textarea><small>Placeholders: {parent} {month} {details} {total}</small></label><div id="payment-recipients">${paymentRecipients()}</div></div><div class="panel comm-panel"><div class="table-heading"><div><h2>Class updates</h2><p class="heading-note">Tell every parent in a class about a cancelled or rescheduled lesson.</p></div></div><div class="comm-form"><label>Class<select id="comm-class">${state.classes.map((group) => `<option value="${group.id}" ${String(group.id) === String(state.commClassId) ? 'selected' : ''}>Class ${group.number} · ${classSchedule(group)}</option>`).join('')}</select></label><label>Update<select id="comm-type">${notices.map(([value, label]) => `<option value="${value}" ${value === state.commType ? 'selected' : ''}>${label}</option>`).join('')}</select></label><label>Lesson date<input id="comm-date" type="date" value="${state.commDate}" /></label>${state.commType === 'day' ? `<label>New date<input id="comm-new-date" type="date" value="${state.commNewDate}" /></label>` : ''}${state.commType !== 'cancel' ? `<label>${state.commType === 'day' ? 'Time (optional)' : 'New time'}<input id="comm-time" type="time" value="${state.commTime}" /></label>` : ''}</div><label class="comm-message">Message<textarea id="class-message" rows="5" dir="rtl">${escapeHtml(state.classMessage ?? classNoticeText(selectedClass))}</textarea><small>{parent} is replaced with each parent’s name. Changing the fields above rewrites the message.</small></label><div id="class-recipients">${classRecipients(selectedClass)}</div></div></div>` }
function classSchedule(group) { return group.lessonTime ? `${group.day} ${new Intl.DateTimeFormat('en-US', { hour: 'numeric', minute: '2-digit' }).format(new Date(`2000-01-01T${group.lessonTime}`))}` : group.day }
function escapeHtml(value) { return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;') }
function parentPhone(parent) { return state.students.find((student) => (student.parent || 'No parent listed') === parent && String(student.phone || '').replace(/\D/g, ''))?.phone || '' }
// wa.me needs the number in international format; 10-digit numbers are treated as US numbers.
function whatsappLink(phone, text) { const digits = String(phone || '').replace(/\D/g, ''); const number = digits.length === 10 ? `1${digits}` : digits; return `https://wa.me/${number}?text=${encodeURIComponent(text)}` }
function whatsappButton(parent, text) { const phone = parentPhone(parent); return `<a class="whatsapp-button" href="${whatsappLink(phone, text)}" target="_blank" rel="noopener" title="${phone ? `Send to ${escapeHtml(phone)}` : 'No phone saved: choose the contact in WhatsApp'}">${phone ? 'Send on WhatsApp' : 'Choose contact'}</a>` }
function paymentMessage(family) { const monthName = new Intl.DateTimeFormat('he-IL', { month: 'long', year: 'numeric' }).format(new Date(state.billingYear, state.billingMonth, 1)); const lines = family.students.map((student, index) => { const { lessons, cost } = family.charges[index]; return `• ${student} – ${lessons === 1 ? 'שיעור אחד' : `${lessons} שיעורים`} × $${cost} = $${(lessons * cost).toFixed(2)}` }); if (family.previousBalance > 0) lines.push(`• יתרה מחודש קודם: $${family.previousBalance.toFixed(2)}`); if (family.previousBalance < 0) lines.push(`• זיכוי מחודש קודם: -$${Math.abs(family.previousBalance).toFixed(2)}`); if (family.paid) lines.push(`• שולם: -$${family.paid.toFixed(2)}`); return state.paymentTemplate.replaceAll('{parent}', family.parent).replaceAll('{month}', monthName).replaceAll('{details}', lines.join('\n')).replaceAll('{total}', `$${family.balance.toFixed(2)}`) }
function paymentRecipients() { const families = billingFamilies(); if (!families.length) return '<p class="heading-note comm-empty">No charges for this month yet. Mark attendance to create them.</p>'; return `<div class="comm-list">${families.map((family) => `<div class="comm-row"><div><strong>${family.parent}</strong><small>${family.students.join(', ')}${parentPhone(family.parent) ? ` · ${parentPhone(family.parent)}` : ' · no phone saved'}</small></div><strong class="${family.balance ? 'coral-text' : 'green-text'}">$${family.balance.toFixed(2)}</strong>${family.balance ? whatsappButton(family.parent, paymentMessage(family)) : '<span class="comm-paid">Paid</span>'}</div>`).join('')}</div>` }
function classNoticeText(group) { if (!group) return ''; const formatDate = (value) => value ? new Intl.DateTimeFormat('he-IL', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(`${value}T12:00`)) : '[תאריך]'; const at = (value) => value ? ` בשעה ${value}` : ''; const lesson = `השיעור של ${formatDate(state.commDate)}${at(group.lessonTime)}`; const body = state.commType === 'cancel' ? `${lesson} מבוטל.` : state.commType === 'time' ? `השיעור של ${formatDate(state.commDate)} יתקיים${at(state.commTime) || ' בשעה [שעה]'}${group.lessonTime ? ` במקום ${group.lessonTime}` : ''}.` : `${lesson} יועבר ל${formatDate(state.commNewDate)}${at(state.commTime || group.lessonTime)}.`; return `שלום {parent},\n${body}\nתודה, סמדר` }
function classRecipients(group) { if (!group) return '<p class="heading-note comm-empty">Create a class first.</p>'; const parents = [...new Set(state.students.filter((student) => (group.studentIds || []).includes(student.id)).map((student) => student.parent || 'No parent listed'))]; if (!parents.length) return '<p class="heading-note comm-empty">No students are assigned to this class.</p>'; const text = state.classMessage ?? classNoticeText(group); return `<div class="comm-list">${parents.map((parent) => `<div class="comm-row"><div><strong>${parent}</strong><small>${state.students.filter((student) => (student.parent || 'No parent listed') === parent && (group.studentIds || []).includes(student.id)).map((student) => student.name).join(', ')}${parentPhone(parent) ? ` · ${parentPhone(parent)}` : ' · no phone saved'}</small></div>${whatsappButton(parent, text.replaceAll('{parent}', parent))}</div>`).join('')}</div>` }
function communicationEvents() { const template = document.querySelector('#payment-template'); if (!template) return; const rewrite = () => { state.classMessage = undefined; render() }; document.querySelector('#comm-month').addEventListener('change', (event) => { state.billingMonth = Number(event.target.value); render() }); document.querySelector('#comm-year').addEventListener('change', (event) => { state.billingYear = Number(event.target.value) || now.getFullYear(); render() }); template.addEventListener('input', (event) => { state.paymentTemplate = event.target.value; try { localStorage.setItem(paymentTemplateKey, event.target.value) } catch {} document.querySelector('#payment-recipients').innerHTML = paymentRecipients() }); document.querySelector('#comm-class')?.addEventListener('change', (event) => { state.commClassId = event.target.value; rewrite() }); document.querySelector('#comm-type')?.addEventListener('change', (event) => { state.commType = event.target.value; rewrite() }); [['#comm-date', 'commDate'], ['#comm-new-date', 'commNewDate'], ['#comm-time', 'commTime']].forEach(([selector, field]) => document.querySelector(selector)?.addEventListener('change', (event) => { state[field] = event.target.value; rewrite() })); document.querySelector('#class-message')?.addEventListener('input', (event) => { state.classMessage = event.target.value; document.querySelector('#class-recipients').innerHTML = classRecipients(state.classes.find((group) => String(group.id) === String(state.commClassId))) }) }
function attendanceTotal(students, daysInMonth) { let total = 0; students.forEach((student) => { for (let day = 1; day <= daysInMonth; day += 1) if (state.attendance[attendanceKey(student.id, day)]) total += 1 }); return total }
function attendanceKey(studentId, day) { const date = `${state.attendanceYear}-${String(state.attendanceMonth + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`; return `${state.attendanceClassId}:${date}:${studentId}` }
function attendanceClassDates(classId, year, monthIndex) { const prefix = `${classId}:${year}-${String(monthIndex + 1).padStart(2, '0')}-`; return new Set(Object.entries(state.attendance).filter(([key, present]) => present && key.startsWith(prefix)).map(([key]) => key.split(':')[1])).size }
function attendanceStudentTotal(studentId, year, monthIndex) { const monthPrefix = `${year}-${String(monthIndex + 1).padStart(2, '0')}-`; return Object.entries(state.attendance).filter(([key, present]) => present && key.split(':')[1].startsWith(monthPrefix) && Number(key.split(':')[2]) === studentId).length }
function attendanceTable(students, daysInMonth) { const isWeekend = (day) => { const weekday = new Date(state.attendanceYear, state.attendanceMonth, day).getDay(); return weekday === 0 || weekday === 6 }; const days = Array.from({ length: daysInMonth }, (_, index) => index + 1); return `<div class="attendance-frame"><table class="attendance-names"><thead><tr><th class="attendance-student-heading">Student</th></tr></thead><tbody>${students.map((student) => `<tr><td class="attendance-student"><span class="attendance-student-name"><span class="avatar ${student.accent || 'teal'}">${initials(student.name)}</span><strong>${student.name}</strong></span></td></tr>`).join('')}</tbody></table><div class="attendance-table-wrap"><table class="attendance-table"><thead><tr>${days.map((day) => `<th class="day-heading ${isWeekend(day) ? 'weekend' : ''}">${day}<small>${new Intl.DateTimeFormat('en-US', { weekday: 'short' }).format(new Date(state.attendanceYear, state.attendanceMonth, day))}</small></th>`).join('')}</tr></thead><tbody>${students.map((student) => `<tr>${days.map((day) => { const key = attendanceKey(student.id, day); return `<td class="attendance-cell ${isWeekend(day) ? 'weekend' : ''}"><button class="attendance-toggle ${state.attendance[key] ? 'present' : ''}" data-action="toggle-attendance" data-key="${key}" title="${state.attendance[key] ? 'Mark absent' : 'Mark present'}">${state.attendance[key] ? '✓' : ''}</button></td>` }).join('')}</tr>`).join('')}</tbody></table></div></div>` }
function emptyStudentState() { return `<div class="empty-state"><div class="empty-icon">＋</div><h2>Your roster is ready for its first name</h2><p>Add a student, then include their parent or guardian and phone number.</p><button class="primary-button" data-action="add-student"><span>+</span> Add your first student</button></div>` }
function emptyClassState() { return `<div class="panel empty-state"><div class="empty-icon">＋</div><h2>No classes yet</h2><p>Create your first group with a weekly day and a cost per student.</p><button class="primary-button" data-action="add-class"><span>+</span> Create your first class</button></div>` }
function studentRows(students) { return students.map((student) => `<tr><td><div class="person-cell"><span class="avatar large ${student.accent || 'teal'}">${initials(student.name)}</span><div><strong>${student.name}</strong><small>Student</small></div></div></td><td><strong>${student.parent}</strong></td><td>${student.phone}</td><td><button class="row-action" data-action="edit-student" data-id="${student.id}">Edit</button><button class="row-delete" data-action="delete-student" data-id="${student.id}" title="Remove student">×</button></td></tr>`).join('') }
function classCard(group) { const assigned = state.students.filter((student) => (group.studentIds || []).includes(student.id)); return `<article class="class-card"><div class="class-card-top"><span class="class-day">${classSchedule(group)}</span><div><button class="row-action" data-action="edit-class" data-id="${group.id}">Edit</button><button class="row-delete" data-action="delete-class" data-id="${group.id}" title="Remove class">×</button></div></div><h2>Class ${group.number}</h2><p>${group.name || 'Weekly Hebrew group'}</p><div class="class-divider"></div><div class="class-meta"><span>Cost per student</span><strong>$${Number(group.cost).toFixed(2)} <small>/ lesson</small></strong></div><div class="class-meta class-size"><span>Students</span><strong>${assigned.length}</strong></div><div class="class-students">${assigned.slice(0, 5).map((student) => `<span class="avatar ${student.accent || 'teal'}" title="${student.name}">${initials(student.name)}</span>`).join('')}${assigned.length > 5 ? `<span class="avatar more">+${assigned.length - 5}</span>` : ''}<button class="add-person" data-action="edit-class" data-id="${group.id}" title="Assign students">+</button></div></article>` }

function backupPage() { const snapshots = state.snapshots; const formatDate = (value) => new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)); const summaryText = (summary) => `${summary.students || 0} students · ${summary.classes || 0} classes · ${summary.attendance || 0} attendance marks · ${summary.billing || 0} payments`; const disabled = state.backupBusy ? 'disabled' : ''; const snapshotList = snapshots === undefined ? '<p class="heading-note">Loading saved backups…</p>' : snapshots === null ? '<p class="backup-note">Automatic cloud backups are not set up yet. Run the latest <code>supabase-schema.sql</code> in the Supabase SQL editor to turn them on.</p>' : snapshots.length ? `<ul class="backup-list">${snapshots.map((snapshot) => `<li><div><strong>${formatDate(snapshot.created_at)}</strong><small>${snapshot.reason === 'daily' ? 'Daily automatic' : snapshot.reason === 'before-restore' ? 'Before a restore' : 'Manual'} · ${summaryText(snapshot.summary || {})}</small></div><div class="backup-actions"><button class="row-action" data-action="download-snapshot" data-id="${snapshot.id}" ${disabled}>Download</button><button class="row-action" data-action="restore-snapshot" data-id="${snapshot.id}" ${disabled}>Restore</button></div></li>`).join('')}</ul>` : '<p class="heading-note">No cloud backups yet. One is taken automatically each day when the app opens.</p>'; return `<div class="page-wrap"><div class="page-header"><div><div class="eyebrow">KEEP YOUR DATA SAFE</div><h1>Backup & restore</h1><p>Save a copy of all students, classes, attendance and payments, and bring it back if something goes missing.</p></div></div><div class="toolbar"><span class="storage-status" id="storage-status">${statusMessage}</span></div><div class="backup-grid"><section class="panel"><h2>Backup file</h2><p class="heading-note">Download everything as one file and keep it on your computer or in Google Drive.</p><div class="backup-buttons"><button class="primary-button" data-action="download-backup" ${disabled}>Download backup</button><button class="secondary-button" data-action="choose-restore-file" ${disabled}>Restore from file</button><input id="restore-file" type="file" accept="application/json,.json" hidden /></div><p class="backup-note">Restoring adds back everything in the backup and updates matching records. It never deletes anything added after the backup.</p></section><section class="panel"><div class="backup-heading"><div><h2>Cloud backups</h2><p class="heading-note">Taken automatically once a day. The last 30 are kept.</p></div>${snapshots ? `<button class="secondary-button" data-action="create-snapshot" ${disabled}>Back up now</button>` : ''}</div>${snapshotList}</section></div></div>` }
function downloadJson(backup) { const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' }); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = `hebrew-with-smadar-backup-${backup.createdAt.slice(0, 10)}.json`; link.click(); setTimeout(() => URL.revokeObjectURL(link.href), 1000) }
async function refreshSnapshots() { state.snapshots = await listSnapshots().catch(() => null); if (state.view === 'backup') render() }
async function runBackupTask(task, doneMessage) { state.backupBusy = true; render(); try { await task(); statusMessage = doneMessage } catch (error) { statusMessage = error.message || 'Backup action failed.' } state.backupBusy = false; render() }
async function restoreBackup(backup, label) { const summary = backupSummary(backup); if (!confirm(`Restore ${label}?\n\n${summary.students} students, ${summary.classes} classes, ${summary.attendance} attendance marks and ${summary.billing} payment records will be added back. Nothing will be deleted.`)) return; await runBackupTask(async () => { await createSnapshot('before-restore').catch(() => {}); await importData(backup); await loadAllData(); await refreshSnapshots() }, `Restored ${label}.`) }

// Pins the first N columns of tables marked data-freeze by laying a clipped copy of the table over the
// left edge of its scroll area. Works on browsers that ignore sticky table cells (iPhone Safari).
function applyFrozenColumns() { document.querySelectorAll('table[data-freeze]:not(.frozen-copy)').forEach((table) => { const wrap = table.parentElement; const host = wrap.parentElement; host.querySelector(':scope > .frozen-overlay')?.remove(); if (wrap.scrollWidth <= wrap.clientWidth + 1) return; const headings = [...table.querySelectorAll('thead th')].slice(0, Number(table.dataset.freeze)); const width = headings.reduce((total, cell) => total + cell.getBoundingClientRect().width, 0); const hostRect = host.getBoundingClientRect(); const wrapRect = wrap.getBoundingClientRect(); const overlay = document.createElement('div'); overlay.className = 'frozen-overlay'; overlay.setAttribute('aria-hidden', 'true'); overlay.style.left = `${wrapRect.left - hostRect.left - host.clientLeft}px`; overlay.style.top = `${wrapRect.top - hostRect.top - host.clientTop}px`; overlay.style.width = `${Math.ceil(width)}px`; const copy = table.cloneNode(true); copy.classList.add('frozen-copy'); copy.querySelectorAll('[id]').forEach((element) => element.removeAttribute('id')); copy.style.width = `${table.offsetWidth}px`; overlay.append(copy); host.classList.add('freeze-host'); host.append(overlay) }) }
let frozenResizeTimer
window.addEventListener('resize', () => { clearTimeout(frozenResizeTimer); frozenResizeTimer = setTimeout(applyFrozenColumns, 150) })
document.fonts?.ready.then(() => applyFrozenColumns())

function attachEvents() { app.removeEventListener('click', handleViewClick); app.addEventListener('click', handleViewClick); document.querySelectorAll('[data-action]').forEach((button) => button.addEventListener('click', () => handleAction(button.dataset.action, button.dataset))); document.querySelector('#student-search')?.addEventListener('input', (event) => { const query = event.target.value.toLowerCase(); const rows = state.students.filter((student) => `${student.name} ${student.parent} ${student.phone}`.toLowerCase().includes(query)); document.querySelector('#student-rows').innerHTML = studentRows(rows); applyFrozenColumns() }); document.querySelector('#attendance-class')?.addEventListener('change', (event) => { state.attendanceClassId = event.target.value; render() }); document.querySelector('#attendance-month')?.addEventListener('change', (event) => { state.attendanceMonth = Number(event.target.value); render() }); document.querySelector('#attendance-year')?.addEventListener('change', (event) => { state.attendanceYear = Number(event.target.value) || now.getFullYear(); render() }); document.querySelector('#billing-month')?.addEventListener('change', (event) => { state.billingMonth = Number(event.target.value); render() }); document.querySelector('#billing-year')?.addEventListener('change', (event) => { state.billingYear = Number(event.target.value) || now.getFullYear(); render() }); document.querySelector('#restore-file')?.addEventListener('change', async (event) => { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; let backup; try { backup = JSON.parse(await file.text()) } catch { setStatus('That file could not be read as a backup.'); return } await restoreBackup(backup, `the backup file ${file.name}`) }); document.querySelector('#reports-year')?.addEventListener('change', (event) => { state.reportsYear = Number(event.target.value) || now.getFullYear(); render() }); communicationEvents() }
function handleViewClick(event) { const button = event.target.closest('[data-view]'); if (!button) return; state.view = button.dataset.view; window.history.replaceState(null, '', `#${state.view}`); if (state.view === 'backup') refreshSnapshots(); if (state.view === 'attendance' && !state.attendanceClassId && state.classes[0]) state.attendanceClassId = state.classes[0].id; render() }
function handleAction(action, data) { if (action === 'download-backup') runBackupTask(async () => downloadJson(await exportData()), 'Backup downloaded.'); if (action === 'choose-restore-file') document.querySelector('#restore-file')?.click(); if (action === 'create-snapshot') runBackupTask(async () => { await createSnapshot('manual'); await refreshSnapshots() }, 'Cloud backup saved.'); if (action === 'download-snapshot') runBackupTask(async () => downloadJson(await getSnapshot(Number(data.id))), 'Backup downloaded.'); if (action === 'restore-snapshot') { const snapshot = state.snapshots?.find((item) => item.id === Number(data.id)); getSnapshot(Number(data.id)).then((backup) => restoreBackup(backup, `the backup from ${new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(snapshot.created_at))}`)).catch((error) => setStatus(error.message)) } if (action === 'add-student') openStudentModal(); if (action === 'edit-student') openStudentModal(Number(data.id)); if (action === 'add-class') openClassModal(); if (action === 'edit-class') openClassModal(Number(data.id)); if (action === 'toggle-attendance') { state.attendance[data.key] = !state.attendance[data.key]; if (!state.attendance[data.key]) delete state.attendance[data.key]; saveAttendanceData(data.key); render() } if (action === 'save-payment') { const parent = data.parent; const row = [...document.querySelectorAll(`[data-parent="${CSS.escape(parent)}"]`)].find((element) => element.classList.contains('paid-input'))?.closest('tr'); const amountPaid = Number(row?.querySelector('.paid-input')?.value || 0); const paymentMethod = row?.querySelector('.payment-method-select')?.value || ''; state.billing[billingKey(parent)] = { amountPaid, paymentMethod }; saveBillingData(); render() } if (action === 'delete-student') { const student = state.students.find((item) => item.id === Number(data.id)); if (student && confirm(`Remove ${student.name} from the roster?`)) { state.students = state.students.filter((item) => item.id !== student.id); state.classes.forEach((group) => { group.studentIds = (group.studentIds || []).filter((id) => id !== student.id) }); deleteStudent(student.id).catch(() => {}); saveStudentsData(); saveClassesData(); render() } } if (action === 'delete-class') { const group = state.classes.find((item) => item.id === Number(data.id)); if (group && confirm(`Remove Class ${group.number}?`)) { state.classes = state.classes.filter((item) => item.id !== group.id); deleteClass(group.id).catch(() => {}); saveClassesData(); render() } } }
function openStudentModal(id) { const existing = state.students.find((student) => student.id === id); const student = existing || { name: '', parent: '', phone: '' }; openModal(`<div class="modal-head"><div><div class="eyebrow">${id ? 'EDIT STUDENT' : 'NEW STUDENT'}</div><h2>${id ? 'Edit student details' : 'Add a student'}</h2></div><button class="close-button" data-close>×</button></div><form id="student-form"><label>Student name<input name="name" value="${student.name}" required placeholder="Enter student name" /></label><label>Parent / guardian<input name="parent" value="${student.parent}" required placeholder="Enter parent or guardian name" /></label><label>Phone number<input name="phone" value="${student.phone}" placeholder="(000) 000-0000" /></label><div class="modal-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">${id ? 'Save changes' : 'Add student'}</button></div></form>`, (root) => root.querySelector('#student-form').addEventListener('submit', (event) => { event.preventDefault(); const form = Object.fromEntries(new FormData(event.target)); if (existing) Object.assign(existing, form); else state.students.push({ id: Date.now(), ...form, accent: accents[state.students.length % accents.length] }); saveStudentsData(); closeModal(); render() })) }
function openClassModal(id) { const existing = state.classes.find((group) => group.id === id); const group = existing || { number: '', name: '', day: 'Monday', lessonTime: '', cost: '', studentIds: [] }; const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']; openModal(`<div class="modal-head"><div><div class="eyebrow">${id ? 'EDIT CLASS' : 'NEW CLASS'}</div><h2>${id ? 'Edit class structure' : 'Create a class'}</h2></div><button class="close-button" data-close>×</button></div><form id="class-form"><div class="form-grid"><label>Class number<input name="number" value="${group.number}" required placeholder="e.g. 1" /></label><label>Day<select name="day">${days.map((day) => `<option ${day === group.day ? 'selected' : ''}>${day}</option>`).join('')}</select></label></div><label>Class name<input name="name" value="${group.name || ''}" placeholder="e.g. Beginners group" /></label><div class="form-grid"><label>Time<input name="lessonTime" type="time" value="${group.lessonTime || ''}" /></label><label>Cost per student / lesson<input name="cost" type="number" min="0" step="0.01" value="${group.cost}" required placeholder="0.00" /></label></div><fieldset><legend>Assign students</legend><div class="student-checks">${state.students.length ? state.students.map((student) => `<label><input type="checkbox" name="studentIds" value="${student.id}" ${(group.studentIds || []).includes(student.id) ? 'checked' : ''} />${student.name}</label>`).join('') : '<span class="muted">Add students first to assign them to a class.</span>'}</div></fieldset><div class="modal-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="primary-button">${id ? 'Save changes' : 'Create class'}</button></div></form>`, (root) => root.querySelector('#class-form').addEventListener('submit', (event) => { event.preventDefault(); const formData = new FormData(event.target); const values = Object.fromEntries(formData); const studentIds = formData.getAll('studentIds').map(Number); const next = { id: existing?.id || Date.now(), number: values.number, name: values.name, day: values.day, lessonTime: values.lessonTime, cost: Number(values.cost), studentIds }; if (existing) Object.assign(existing, next); else state.classes.push(next); saveClassesData(); closeModal(); render() })) }
function openModal(content, onReady) { const root = document.querySelector('#modal-root'); root.innerHTML = `<div class="modal-backdrop"><div class="modal">${content}</div></div>`; root.querySelectorAll('[data-close]').forEach((button) => button.addEventListener('click', closeModal)); onReady?.(root) }
function closeModal() { document.querySelector('#modal-root').innerHTML = '' }
async function loadAllData() { state.students = await loadStudents(); state.classes = await loadClasses(); state.attendance = await loadAttendance(); state.billing = await loadBilling(); if (!state.classes.some((group) => group.id === state.attendanceClassId)) state.attendanceClassId = state.classes[0]?.id || ''; if (!state.classes.some((group) => String(group.id) === String(state.commClassId))) state.commClassId = state.classes[0]?.id || '' }
async function bootstrap() { render(); try { await loadAllData(); setStatus(storageMode === 'cloud' ? 'Synced with Supabase' : 'Saved in this browser'); render(); autoSnapshot().finally(() => { if (state.view === 'backup') refreshSnapshots() }) } catch { setStatus('Could not reach Supabase. Showing saved device data.'); render() } }
bootstrap()